mapper.select:
SELECT COUNT(*)
FROM tb_board B
WHERE 1 = 1


    AND (
        B.BOARD_SJ LIKE '%' || #{searchRequest.keyword} || '%'
        OR B.BOARD_CN LIKE '%' || #{searchRequest.keyword} || '%'
    )






            AND B.DEPT_CD = #{deptCd}


            AND B.BOARD_TYPE_CD = #{boardTypeCd}

SELECT BOARD_ID ,BOARD_TYPE_CD ,BOARD_SJ ,BOARD_CN ,FRST_RGTR_ID ,FRST_REG_DT ,LAST_MDFR_DT ,BOARD_ATCH_FILE_ID ,DEPT_CD ,PROJ_ID ,IMPRTNT_YN ,CMNT_USE_YN ,VIEW_CNT FROM tb_board B WHERE 1 = 1
AND B.DEPT_CD = #{deptCd}
AND B.BOARD_TYPE_CD = #{boardTypeCd}
AND B.BOARD_SJ LIKE '%'|| #{searchRequest.keyword} || '%' OR B.BOARD_CN LIKE '%'|| #{searchRequest.keyword} || '%'
ORDER BY B.BOARD_ID DESC
OFFSET #{getOffset} ROWS FETCH NEXT #{getPageSize} ROWS ONLY

SELECT DISTINCT B.BOARD_TYPE_CD AS boardTypeCd, B.DEPT_CD AS deptCd, CASE WHEN B.BOARD_TYPE_CD = 'FREE' THEN '자유게시판' WHEN B.BOARD_TYPE_CD = 'ANON' THEN '익명게시판' WHEN B.BOARD_TYPE_CD = 'NOTICE' THEN '공지사항' WHEN B.BOARD_TYPE_CD = 'DEPT' THEN D.DEPT_NM
ELSE B.BOARD_SJ END AS boardName FROM tb_board B
LEFT JOIN tb_department D ON B.DEPT_CD = D.DEPT_CD WHERE 1 = 1 AND (
1 = 1
1 = 0
OR B.BOARD_TYPE_CD IN ('FREE', 'ANON', 'NOTICE', 'DEPT') OR B.FRST_RGTR_ID = #{empId} OR B.DEPT_CD = #{myDeptCd}
OR B.DEPT_CD IN
#{scopeDeptCd}
)
